from Crypto.Cipher import AES
import base64

class PiiFieldEncryptor:
    def __init__(self):
        key_hex = os.environ.get('PII_FIELD_KEY_HEX')
        if not key_hex:
            raise RuntimeError('PII_FIELD_KEY_HEX required')
        self._key = bytes.fromhex(key_hex)
        if len(self._key) != 32:
            raise ValueError('PII field key must be 256 bits')

    def encrypt(self, ssn):
        cipher = AES.new(self._key, AES.MODE_GCM)
        ct, tag = cipher.encrypt_and_digest(ssn.encode())
        return base64.b64encode(cipher.nonce + tag + ct).decode()

    def decrypt(self, enc):
        raw = base64.b64decode(enc)
        nonce, tag, ct = raw[:16], raw[16:32], raw[32:]
        return AES.new(self._key, AES.MODE_GCM,
                       nonce=nonce).decrypt_and_verify(ct, tag).decode()

